'use strict';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=v=>v===null||v===undefined||v===''?null:Number.isFinite(Number(v))?Number(v):null;
const num=v=>n(v)===null?'—':n(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const money=v=>n(v)===null?'—':'¥'+num(v),signed=v=>n(v)===null?'—':(n(v)>0?'+':'')+num(v),pct=v=>n(v)===null?'—':signed(v)+'%',tone=v=>n(v)>0?'up':n(v)<0?'down':'';
const dt=v=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—';
const titles={workbench:'对话工作台',library:'策略库',holdings:'我的持仓',watchlist:'我的自选',plans:'我的计划',history:'回测记录',account:'连接与设置',settings:'模型设置'};
const state={csrf:'',catalog:[],variants:[],plans:[],runs:[],events:[],watchlist:[],showcases:{},showcaseLoading:new Set(),planPerformanceLoading:false,nav:'workbench',selected:null,variant:null,result:null,job:null,busy:false,backtestRevision:0,detailTab:'editor',paramEditing:false,paramDraft:null,paramsExpanded:false,composerContext:null,planToSave:null,planSaving:false,pendingCode:'',holdings:null,holdingsError:'',analysis:null,analysisError:'',holdingsTab:'list',selectedHoldingCode:'',holdingDetails:{},holdingsSearch:'',holdingsSort:'amount',holdingsAgentContext:null,holdingsAgentOpen:false,agentOpen:false,agentPageFocus:null,runFocus:null,accountBusy:false,accountLoginMode:'login',accountLoginMessage:'',accountLoginOpenedUrl:'',drill:null,defaultLoading:null,shareCard:null,shareImport:null};
const D={enabled:Boolean(window.fundDesktop),settings:null,status:null,sessions:[],current:null,messages:[],tools:new Map(),running:false,initialized:false,pendingInput:null,turnStartedAt:null,turnMessageStart:0};
let toastTimer,planMonitorTimer,jobTimer;const showcasePromises=new Map();

async function api(path,body){const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),120000);try{const r=await fetch(path,{method:body===undefined?'GET':'POST',cache:'no-store',signal:ctrl.signal,headers:body===undefined?{}:{'Content-Type':'application/json','X-Workbench-Token':state.csrf},body:body===undefined?undefined:JSON.stringify(body)});const p=await r.json();if(!r.ok||!p.ok)throw new Error(p.error?.message||'本地服务请求失败。');return p.data}catch(e){if(e.name==='AbortError')throw new Error('请求超时，请稍后重试。');throw e}finally{clearTimeout(timer)}}
async function desktopCall(p){const r=await p;if(!r?.ok)throw new Error(r?.error||'桌面 Agent 操作失败。');return r.data}
function toast(text){const node=$('#panda-toast');if(!node)return;node.textContent=text;node.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('show'),4200)}
function button(label,action,attrs='',cls=''){return `<button type="button" class="panda-button ${cls}" data-action="${action}" ${attrs}>${label}</button>`}
function findStrategy(id){return state.catalog.find(x=>x.id===id)}
function currentVariant(id){return state.variant?.strategyId===id?state.variant:state.variants.filter(x=>x.strategyId===id).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)))[0]}
function heading(eyebrow,title,desc,actions=''){return `<div class="panda-heading"><div><h1>${esc(title)}</h1>${desc?`<p>${esc(desc)}</p>`:''}</div><div class="panda-heading-actions">${actions}</div></div>`}
function shortRule(item){return ({'rsi-profit':'低位分批买入，达到目标收益后止盈。','nav-swing':'净值相对低位买入，相对高位减仓。','trend-strength':'走势转强时买入，转弱时退出。','gem-valuation':'创业板估值低时多投，高时少投或减仓。','industry-trend':'每月比较行业走势，持有趋势较强的基金。'})[item.id]||item.description}
function disclosure(title,content,cls=''){return `<details class="panda-disclosure ${cls}"><summary>${title}</summary><div>${content}</div></details>`}
function inlineMarkdown(value){let text=esc(value);return text.replace(/`([^`\n]+)`/g,'<code>$1</code>').replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/\[([^\]]+)\]\((https:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noreferrer">$1</a>')}
function renderMarkdown(value){const parts=String(value||'').split(/```/);return parts.map((part,index)=>{if(index%2)return `<pre><code>${esc(part.replace(/^\w+\n/,'').replace(/\n$/,''))}</code></pre>`;const lines=part.split('\n'),out=[];for(let i=0;i<lines.length;){const line=lines[i];if(!line.trim()){i++;continue}if(/^\s*[-*]\s+/.test(line)){const items=[];while(i<lines.length&&/^\s*[-*]\s+/.test(lines[i]))items.push(lines[i++].replace(/^\s*[-*]\s+/,''));out.push(`<ul>${items.map(x=>`<li>${inlineMarkdown(x)}</li>`).join('')}</ul>`);continue}if(/^\s*\d+\.\s+/.test(line)){const items=[];while(i<lines.length&&/^\s*\d+\.\s+/.test(lines[i]))items.push(lines[i++].replace(/^\s*\d+\.\s+/,''));out.push(`<ol>${items.map(x=>`<li>${inlineMarkdown(x)}</li>`).join('')}</ol>`);continue}const h=line.match(/^(#{1,3})\s+(.+)$/);if(h){out.push(`<h${h[1].length+2}>${inlineMarkdown(h[2])}</h${h[1].length+2}>`);i++;continue}const p=[line];i++;while(i<lines.length&&lines[i].trim()&&!/^(#{1,3})\s+|^\s*[-*]\s+|^\s*\d+\.\s+/.test(lines[i]))p.push(lines[i++]);out.push(`<p>${p.map(inlineMarkdown).join('<br>')}</p>`)}return out.join('')}).join('')}

function defaultParamsMatch(run,item){return run?.status==='ok'&&run.strategyVersion===item.version&&(item.params||[]).every(spec=>String(run.parameters?.[spec.key]??'')===String(item.defaultParams?.[spec.key]??spec.default??''))}
function showcaseRun(item){return state.runs.filter(run=>run.strategyId===item.id&&defaultParamsMatch(run,item)&&n(run.metrics?.excessReturnPct)!==null).sort((a,b)=>(n(b.metrics?.excessReturnPct)??-Infinity)-(n(a.metrics?.excessReturnPct)??-Infinity))[0]||null}
function showcaseBest(item){return state.showcases[item.id]?.best||showcaseRun(item)?.result||null}
function sortedStrategies(){return state.catalog.map((item,index)=>({item,index,excess:n(showcaseBest(item)?.metrics?.excessReturnPct)})).sort((a,b)=>(b.excess??-Infinity)-(a.excess??-Infinity)||a.index-b.index).map(row=>row.item)}
function strategyCard(item){
 const best=showcaseBest(item),m=best?.metrics||{},absolute=m.absoluteReturnPct??m.returnPct;
 const performance=best?`<div class="strategy-performance"><div class="strategy-primary-metric"><span>超额收益</span><b class="${tone(m.excessReturnPct)}">${pct(m.excessReturnPct)}</b></div><div class="strategy-secondary-metrics"><span>策略累计收益 <b class="${tone(absolute)}">${pct(absolute)}</b></span><span>年化波动率 <b>${n(m.volatilityPct)===null?'—':num(m.volatilityPct)+'%'}</b></span></div><small>${esc(best.candidateName||best.fundCode||'固定行业基金池')}</small><small>${esc(best.period?.start||'—')} — ${esc(best.period?.end||best.dataAsOf||'—')}</small></div>`:`<div class="strategy-performance empty"><strong>${state.showcaseLoading.has(item.id)?'正在验证默认案例':'暂无可用回测'}</strong><small>${state.showcaseLoading.has(item.id)?'读取候选基金与基准数据':'进入详情查看缺失数据'}</small></div>`;
 return `<article class="panda-strategy-card"><div class="strategy-card-head"><span class="strategy-glyph">${esc(item.symbol||'◇')}</span><span class="strategy-badge">${esc(item.category)}</span></div><h3>${esc(item.name)}</h3><p>${esc(shortRule(item))}</p>${performance}<div class="strategy-card-footer"><small>${item.codeRequired===false?'固定基金池历史案例':(item.showcaseCandidates?.length||1)>1?'候选池内历史优选案例':'固定基金历史案例'}</small>${button('查看回测 →','open-strategy',`data-id="${esc(item.id)}"`,'quiet')}</div></article>`
}
function conversationActive(){return D.messages.length>0||D.running||Boolean(D.pendingInput)}
function home(){if(conversationActive())return '<div id="agent-conversation-host" class="panda-conversation-page"></div>';return `<div class="panda-workbench-idle"><div class="panda-start-hero"><h1>想找投资方法，还是看看已有持仓？</h1><div class="panda-hero-actions">${button('帮我选策略','find-strategy','','primary')}<button class="panda-button" data-nav="holdings">看看我的持仓</button></div></div><section class="panda-workspace-block strategy-block"><div class="panda-section-head"><h2>策略</h2><button class="link-button" data-nav="library">查看全部 →</button></div><p class="panda-section-caption">默认案例按超额收益排序，标的与区间可能不同；历史回测不代表未来收益。</p><div class="panda-strategy-grid">${sortedStrategies().map(strategyCard).join('')}</div></section><section class="panda-workspace-block my-block"><div class="panda-section-head"><h2>我的</h2></div><div class="panda-my-grid"><button data-nav="holdings"><span>◫</span><strong>持仓</strong><small>${state.holdings?state.holdings.funds?.length+' 只基金':'连接账户后查看'}</small></button><button data-nav="watchlist"><span>☆</span><strong>自选</strong><small>${state.watchlist.length} 只基金</small></button><button data-nav="plans"><span>▤</span><strong>计划</strong><small>${state.plans.filter(x=>x.status==='active').length} 份跟踪中</small></button></div></section><div id="agent-composer-host" class="panda-bottom-composer-host"></div></div>`}
function library(){return `${heading('','策略','默认案例按超额收益排序；标的、区间与现金流可能不同，不宜直接比较优劣。')}<div class="panda-strategy-grid">${sortedStrategies().map(strategyCard).join('')}</div><p class="panda-section-caption">历史回测不代表未来收益。进入策略查看规则、费用与比较基准。</p>`}
function parameterChoice(value){return ({stable:'等待确认',sensitive:'更快响应',confirmed:'转强后投入',early:'提前响应',weekly:'每周',monthly:'每月',equal:'等额分配',rank:'按排名分配',score:'按得分分配',vol:'低波动多配'})[value]??value}
function parameterHelp(spec){return ({action_mode:'选择等待低位确认，或更快响应。',trend_mode:'选择转强后投入，或趋势已强时提前响应。',weight_scheme:'选择行业之间的资金分配方式。'})[spec.key]||spec.help||'策略计算参数'}
function paramField(spec,params,editable,index){const value=params?.[spec.key]??spec.default??'',hidden=!state.paramsExpanded&&index>=3?' is-collapsed':'',range=spec.choices?spec.choices.join(' / '):`${spec.min}–${spec.max} ${spec.unit||''}`;const control=editable?(spec.choices?`<select aria-label="${esc(spec.label)}" name="param-${esc(spec.key)}">${spec.choices.map(c=>`<option value="${esc(c)}" ${String(c)===String(value)?'selected':''}>${esc(parameterChoice(c))}</option>`).join('')}</select>`:`<div class="panda-number-input"><input aria-label="${esc(spec.label)}" type="number" name="param-${esc(spec.key)}" value="${esc(value)}" min="${esc(spec.min)}" max="${esc(spec.max)}" step="${esc(spec.step||1)}" required><span>${esc(spec.unit||'')}</span></div>`):`<div class="panda-param-value"><strong>${esc(parameterChoice(value))}</strong><span>${esc(spec.unit||'')}</span></div>`;return `<div class="panda-field panda-param-card${hidden}"><label title="可选范围：${esc(range)}"><b>${esc(spec.label)}</b><span>：${esc(parameterHelp(spec))}</span></label>${control}</div>`}
function paramsFromForm(form,item){const raw=Object.fromEntries(new FormData(form)),params={};for(const spec of item.params||[])params[spec.key]=spec.choices?raw['param-'+spec.key]:Number(raw['param-'+spec.key]);if(String(raw.definition||'').trim()){let definition;try{definition=JSON.parse(raw.definition)}catch{throw new Error('受控策略定义不是有效 JSON。')}if(definition.engine!==item.id)throw new Error('策略引擎不可更换；请选择另一张策略卡。');if(!definition.parameters||typeof definition.parameters!=='object'||Array.isArray(definition.parameters))throw new Error('策略定义缺少 parameters。');const supported=new Set((item.params||[]).map(x=>x.key)),unknown=Object.keys(definition.parameters).filter(x=>!supported.has(x));if(unknown.length)throw new Error('当前 Skill 不支持参数：'+unknown.join('、'));for(const spec of item.params||[])if(Object.hasOwn(definition.parameters,spec.key))params[spec.key]=definition.parameters[spec.key]}return {raw,params}}
function ruleDefinition(item,params){return JSON.stringify({engine:item.id,baseVersion:item.version,parameters:params},null,2)}
function parameterModule(item,params,code,example,variant){const editable=state.paramEditing,entries=[];entries.push(`<div class="panda-field panda-param-card panda-fund-contract"><label><b>研究标的</b><span>：${item.codeRequired===false?'按固定行业基金池运行':'用于本次回测的场外基金'}</span></label>${editable&&item.codeRequired!==false?`<input aria-label="基金代码" name="code" inputmode="numeric" maxlength="6" pattern="[0-9]{6}" value="${esc(code)}" placeholder="6 位基金代码" required>`:`<div class="panda-param-value"><strong>${item.codeRequired===false?'固定行业基金池':esc(code||'—')}</strong>${code===example?.fundCode?`<span>${esc(example?.candidateName||'')}</span>`:''}</div><input type="hidden" name="code" value="${esc(code)}">`}</div>`);for(const [index,spec] of (item.params||[]).entries())entries.push(paramField(spec,params,editable,index+1));return `<section class="panda-backtest-params"><input type="hidden" name="variantId" value="${esc(variant?.id||'')}"><input type="hidden" name="name" value="${esc(variant?.name||item.name)}"><input type="hidden" name="description" value="${esc(variant?.description||item.description)}"><div class="panda-backtest-params-head"><div><strong>本次回测配置</strong><small>${state.busy?'正在计算这份配置':editable?(state.result?'编辑中 · 左侧仍为上次结果':'编辑中 · 尚未回测'):state.result?.status==='ok'?'与左侧结果使用同一配置':'待回测验证'}</small></div>${button(editable?'取消':'修改',editable?'cancel-param-edit':'edit-params',state.busy?'disabled':'','quiet')}</div><div class="panda-form-grid">${entries.join('')}</div>${entries.length>3?button(state.paramsExpanded?'收起参数':'展开全部 '+entries.length+' 项','toggle-params','','quiet panda-expand-params'):''}${editable?`<div class="panda-detail-actions"><button class="panda-button primary" type="submit" name="intent" value="run" ${state.busy?'disabled':''}>${state.busy?'计算中…':'重新回测'}</button><button class="panda-button quiet" type="submit" name="intent" value="save" ${state.busy?'disabled':''}>保存配置</button></div>`:''}${disclosure('参数定义与范围',`<dl>${(item.params||[]).map(x=>`<dt>${esc(x.label)}</dt><dd>${esc(x.choices?x.choices.join(' / '):x.min+'–'+x.max+' '+(x.unit||''))} · 默认 ${esc(x.default)}</dd>`).join('')}</dl><pre>${esc(ruleDefinition(item,params))}</pre>`)}</section>`}
function jobPanel(){if(!state.job)return '';const stage={queued:'等待计算',validating:'参数校验','loading-data':'读取真实数据',calculating:'运行确定性回测',rendering:'整理结果',completed:'已完成',failed:'失败'}[state.job.stage]||state.job.stage;return `<section class="panda-job"><div class="panda-job-head"><strong>${esc(stage)}</strong><span>${esc(state.job.progress||0)}% · ${num((state.job.elapsedMs||0)/1000)} 秒</span></div><div class="panda-progress"><i style="width:${Math.max(0,Math.min(100,state.job.progress||0))}%"></i></div><div class="panda-stage-row">${['参数校验','读取数据','策略计算','整理结果'].map((x,i)=>`<span class="${(state.job.progress||0)>[10,30,65,90][i]?'done':''}">${x}</span>`).join('')}</div><details class="panda-run-logs"><summary>运行日志</summary>${(state.job.logs||[]).map(x=>`<p><time>${esc(String(x.at||'').slice(11,19))}</time>${esc(x.message)}</p>`).join('')}</details></section>`}
function lineChart(rows,hasBenchmark=false,trades=[]){if(!rows?.length)return '';const first=key=>n(rows.find(r=>n(r[key])!==null&&n(r[key])!==0)?.[key]),baseValue=first('value'),baseBenchmark=first('benchmark'),plot=rows.map(r=>{const value=n(r.value),benchmark=n(r.benchmark);return {date:r.date,value:baseValue&&value!==null?(value/baseValue-1)*100:null,benchmark:hasBenchmark&&baseBenchmark&&benchmark!==null?(benchmark/baseBenchmark-1)*100:null}}),values=plot.flatMap(r=>[r.value,r.benchmark]).filter(v=>v!==null&&Number.isFinite(v));if(!values.length)return '';const lo=Math.min(0,...values),hi=Math.max(0,...values),pad=Math.max((hi-lo)*.12,2),min=lo-pad,max=hi+pad,left=64,right=694,top=20,bottom=226,width=right-left,height=bottom-top,x=i=>left+i/Math.max(1,plot.length-1)*width,y=v=>top+(max-v)/(max-min)*height,points=key=>plot.map((r,i)=>r[key]===null?'':`${x(i).toFixed(1)},${y(r[key]).toFixed(1)}`).filter(Boolean).join(' '),yTicks=Array.from({length:5},(_,i)=>max-(max-min)*i/4),xIndexes=[0,Math.floor((plot.length-1)/3),Math.floor((plot.length-1)*2/3),plot.length-1].filter((v,i,a)=>a.indexOf(v)===i),nearest=date=>{const target=Date.parse(date);let best=0,diff=Infinity;plot.forEach((r,i)=>{const d=Math.abs(Date.parse(r.date)-target);if(d<diff){best=i;diff=d}});return best},grouped=[...new Map((trades||[]).map(t=>[`${t.date}-${t.side}`,t])).values()],markerRows=grouped.length<=36?grouped:Array.from({length:36},(_,i)=>grouped[Math.round(i*(grouped.length-1)/35)]),markers=markerRows.map(t=>{const i=nearest(t.date),v=hasBenchmark&&plot[i]?.benchmark!==null?plot[i]?.benchmark:plot[i]?.value;if(v===null||v===undefined)return '';const cls=t.side==='buy'?'chart-buy':'chart-sell',label=t.side==='buy'?'买':'卖';return `<g class="chart-trade ${cls}"><circle cx="${x(i)}" cy="${y(v)}" r="4.5"><title>${esc(t.date)} · ${t.side==='buy'?'买入':'卖出'} · ${money(t.amount)}</title></circle><text x="${x(i)}" y="${y(v)-8}">${label}</text></g>`}).join('');return `<svg class="panda-chart" viewBox="0 0 720 270" role="img" aria-label="历史累计收益率曲线"><text class="axis-title" x="16" y="16">累计收益率</text>${yTicks.map(v=>`<g><line class="grid" x1="${left}" y1="${y(v)}" x2="${right}" y2="${y(v)}"/><text class="axis-label" x="${left-9}" y="${y(v)+3}">${v.toFixed(1)}%</text></g>`).join('')}<line class="zero-line" x1="${left}" y1="${y(0)}" x2="${right}" y2="${y(0)}"/><polyline class="strategy-line" points="${points('value')}"/>${hasBenchmark?`<polyline class="benchmark-line" points="${points('benchmark')}"/>`:''}${markers}${xIndexes.map(i=>`<text class="date" x="${x(i)}" y="252" style="text-anchor:${i===0?'start':i===plot.length-1?'end':'middle'}">${esc(plot[i]?.date||'')}</text>`).join('')}</svg>`}
function chart(result){const curve=result?.curve||[];return curve.length?lineChart(curve,true,result.trades||[]):'<div class="panda-result-empty"><div><span class="result-mark">◌</span><strong>暂无可绘制曲线</strong></div></div>'}
function tradesTable(result){const rows=result?.trades;if(!Array.isArray(rows))return '<p class="panda-history-note">旧记录未保存交易明细。</p>';if(!rows.length)return '<p class="panda-history-note">本区间没有触发买卖。</p>';let units=0;const enriched=rows.map(x=>{if(result.fundCode&&n(x.nav)>0&&n(x.amount)!==null)units=Math.max(0,units+(x.side==='buy'?1:-1)*n(x.amount)/n(x.nav));return {...x,displayHolding:n(x.holdingAmount)??(result.fundCode&&n(x.nav)!==null?units*n(x.nav):null)}}).reverse();const table=list=>`<div class="panda-table-wrap"><table class="panda-table"><thead><tr><th>日期 / 依据</th><th>当次交易金额</th><th>交易后持仓金额</th></tr></thead><tbody>${list.map(x=>`<tr><td>${esc(x.date)}<small>${esc(x.reason)}</small></td><td class="trade-${esc(x.side)}">${x.side==='buy'?'买入':'卖出'}<strong>${money(x.amount)}</strong></td><td>${money(x.displayHolding)}</td></tr>`).join('')}</tbody></table></div>`;return table(enriched.slice(0,5))+(rows.length>5?disclosure('查看其余 '+(rows.length-5)+' 笔交易',table(enriched.slice(5))):'')}
function resultView(result,allowPlan=true,parameterMarkup=''){return `${detailBacktest(result)}${parameterMarkup}${result?.status==='ok'?`<div class="panda-result-tabs"><strong>交易依据</strong><span>${result.trades?.length??'—'} 笔</span></div>${tradesTable(result)}${allowPlan?button('保存为计划','save-plan','','primary'):''}`:''}`}
function detailBacktest(result){if(!result)return `<div class="panda-result-empty"><div><span class="result-mark">◌</span><strong>${state.busy?'正在计算':'正在准备默认回测'}</strong><p>结果将使用真实历史数据。</p></div></div>`;if(result.status!=='ok')return `<div class="panda-result-blocked"><b>!</b><div><strong>暂无法判断</strong><p>${esc((result.missingData||[]).join('；')||'数据不完整，请重新回测。')}</p></div></div>`;const m=result.metrics||{},f=result.cashFlow||{},absolute=m.absoluteReturnPct??m.returnPct;const metrics=[['策略累计收益',pct(absolute),tone(absolute)],['超额收益',pct(m.excessReturnPct),tone(m.excessReturnPct)],['最大回撤',n(m.maxDrawdownPct)===null?'—':num(m.maxDrawdownPct)+'%',tone(m.maxDrawdownPct)],['年化波动率',n(m.volatilityPct)===null?'—':num(m.volatilityPct)+'%','']];return `<div class="panda-metrics">${metrics.map(([label,value,color])=>`<div><small>${label}</small><strong class="${color}">${value}</strong></div>`).join('')}</div><div class="panda-chart-wrap">${chart(result)}<div class="panda-chart-legend"><span><i class="strategy"></i>策略</span><span><i class="dash"></i>${esc(result.benchmarkName||'基准')}</span><span><i class="buy"></i>买入</span><span><i class="sell"></i>卖出</span></div></div><p class="panda-essential-note">历史模拟，非账户实际收益。${n(f.fees)===null?'手续费未计入（缺少完整费率）。':'已计费用 '+money(f.fees)+'。'} 数据截至 ${esc(result.dataAsOf||'—')}。</p>${disclosure('资金明细与计算口径',`<div class="panda-extra-metrics"><span>累计投入 <b>${money(f.totalInvested)}</b></span><span>期末金额 <b>${money(f.endingValue)}</b></span><span>模拟盈亏 <b class="${tone(f.netProfit)}">${signed(f.netProfit)}</b></span><span>资金收益率 <b class="${tone(m.capitalReturnPct)}">${pct(m.capitalReturnPct)}</b></span><span>同期基准收益 <b class="${tone(m.benchmarkReturnPct)}">${pct(m.benchmarkReturnPct)}</b></span></div><p>${esc(result.audit?.formula||'超额收益 = 策略同期累计收益率 - 同期基准收益率')}</p><p>${result.audit?.passed?'计算校验通过':'此记录尚未完成新口径校验'} · 来源：${esc(result.source||'旧记录未保存')} · 策略 v${esc(result.strategyVersion||'—')}</p><p>${esc(f.feeNote||'')} ${esc(result.riskStatement||'历史回测不代表未来收益。')}</p>`)}`}
function detailControls(result,parameterMarkup){return `${parameterMarkup}<div class="panda-result-tabs"><strong>交易依据</strong><span>${result?.status==='ok'?(result.trades?.length??'—')+' 笔':'等待回测'}</span></div><div class="panda-detail-evidence">${result?.status==='ok'?tradesTable(result):'<p class="panda-history-note">完成回测后查看买卖依据。</p>'}</div>`}
function detail(item){const variant=state.variant?.strategyId===item.id?state.variant:null,example=showcaseBest(item),saved=state.result?.strategyId===item.id?state.result:null,params=state.paramDraft?.params||saved?.parameters||variant?.params||item.defaultParams||{},code=state.paramDraft?.code??saved?.fundCode??variant?.fundCode??example?.fundCode??item.defaultFundCode??'',versions=state.variants.filter(x=>x.strategyId===item.id);const versionPanel=versions.length?disclosure('已保存的配置 · '+versions.length,versions.map(v=>`<button type="button" class="panda-version-row" data-action="load-variant" data-id="${esc(v.id)}"><strong>${esc(v.name)} · v${v.version}</strong><small>${esc(v.fundCode||'固定基金池')} · ${esc(dt(v.updatedAt))}</small></button>`).join('')):'';const parameters=parameterModule(item,params,code,example,variant);return `<div class="panda-detail-shell"><section class="panda-detail-intro"><div class="panda-detail-titlebar"><button class="panda-back" data-action="back-library">← 策略</button>${state.result?.status==='ok'?button('分享','share-result','','quiet'):''}</div><div class="panda-strategy-title"><h1>${esc(item.name)}</h1><p>${esc(shortRule(item))}</p>${disclosure('了解规则与适用范围',`<ul>${(item.rules||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p><b>适合：</b>${esc(item.suitableFor)}</p><p><b>需要接受：</b>${esc(item.tradeoff)}</p><p>${esc(item.dataBasis)}</p>`)}</div>${versionPanel}</section>${state.job?.status==='completed'?disclosure('本次运行记录',jobPanel()):jobPanel()}<form id="panda-strategy-form" class="panda-detail-form" data-editing="${state.paramEditing}"><div class="panda-detail-context"><div><strong>${esc(saved?.candidateName||saved?.fundCode||code||'固定行业基金池')}</strong><span>${saved?.period?esc(saved.period.start)+' — '+esc(saved.period.end):'回测区间待确认'}</span><small>${state.paramEditing?'参数编辑中 · 重新回测后更新结果':state.busy?'正在重新计算':saved?.status==='ok'?'结果、配置和交易依据对应同一次回测':'默认回测'}</small></div>${!state.paramEditing&&saved?.status==='ok'?button('保存为计划','save-plan',state.busy?'disabled':'','primary'):''}</div><div class="panda-detail-workspace"><section class="panda-backtest-column"><h2>回测结果</h2>${detailBacktest(saved)}</section><section class="panda-controls-column">${detailControls(saved,parameters)}</section></div></form></div>`}
function holdingsPage(){
 const head=heading('','我的持仓',state.holdings?'同花顺账户 · '+dt(state.holdings.fetchedAt):'连接账户后查看真实持仓',state.holdings?`${button('分析持仓','analyze-holdings','','primary')}${button('刷新','refresh-holdings','','quiet')}`:'');
 if(state.holdingsError)return `${head}<div class="panda-result-blocked"><b>!</b><div><strong>账户数据暂不可用</strong><p>${esc(state.holdingsError)}</p>${button('前往连接','nav','data-nav="account"','primary')}</div></div>`;
 if(!state.holdings)return `${head}<div class="panda-loading"><i></i>正在读取账户…</div>`;
 const summary=state.holdings.summary||{},funds=state.holdings.funds||[],p=holdingPerformance(funds,summary);
 return `${head}<section class="holdings-summary" aria-label="账户概览"><div><small>基金资产</small><strong>${money(summary.totalAmount)}</strong></div><div><small>最新日收益</small><strong class="${tone(p.latestIncome)}">${signed(p.latestIncome)}</strong></div><div><small>累计持有收益</small><strong class="${tone(p.holdingIncome)}">${signed(p.holdingIncome)}</strong></div></section><p class="panda-essential-note">日收益按各基金最近净值日汇总，日期可能不同。${p.missingCount?'其中 '+p.missingCount+' 只缺少日收益数据。':''}</p>${disclosure('账户明细',`<div class="panda-extra-metrics"><span>已确认 <b>${money(summary.confirmedAmount)}</b></span><span>待确认 <b>${money(summary.pendingAmount)}</b></span><span>持仓基金 <b>${funds.length} 只</b></span><span>涨 / 跌 / 平 <b>${p.upCount} / ${p.downCount} / ${p.flatCount}</b></span></div>`)}${holdingsModule(funds,summary.totalAmount)}`
}
function holdingPerformance(funds,summary={}){
  const confirmed=(funds||[]).filter(f=>f.holdVol!=='待确认'),dailyRows=confirmed.map(f=>n(f.newestIncome)).filter(v=>v!==null),latestIncome=dailyRows.length?dailyRows.reduce((a,b)=>a+b,0):null;
  const holdingRows=confirmed.map(f=>n(f.holdIncome)).filter(v=>v!==null),holdingIncome=n(summary.holdIncome)??(holdingRows.length?holdingRows.reduce((a,b)=>a+b,0):null),confirmedAmount=n(summary.confirmedAmount)??confirmed.reduce((a,f)=>a+(n(f.totalAmount)||0),0),openingAmount=latestIncome!==null?confirmedAmount-latestIncome:null;
  return {latestIncome,holdingIncome,dailyRate:openingAmount&&openingAmount>0?latestIncome/openingAmount*100:null,dailyCount:dailyRows.length,confirmedCount:confirmed.length,upCount:dailyRows.filter(v=>v>0).length,downCount:dailyRows.filter(v=>v<0).length,flatCount:dailyRows.filter(v=>v===0).length,missingCount:confirmed.length-dailyRows.length};
}

function holdingsAgentSection(){return ''}
function holdingsModule(funds,totalAmount){const tab=state.holdingsTab||'list';return `<section class="holdings-module"><div class="holdings-tabbar" role="tablist" aria-label="持仓模块"><button type="button" role="tab" aria-selected="${tab==='list'}" class="${tab==='list'?'active':''}" data-holdings-tab="list">持仓</button><button type="button" role="tab" aria-selected="${tab==='backtest'}" class="${tab==='backtest'?'active':''}" data-holdings-tab="backtest">组合历史模拟</button></div><div class="holdings-tab-content" role="tabpanel">${tab==='list'?holdingsList(funds,totalAmount):portfolioPanel()}</div></section>`}
function holdingsList(funds,totalAmount){
  const rows=[...funds].sort((a,b)=>{
    if(state.holdingsSort==='income')return (n(b.holdIncome)||0)-(n(a.holdIncome)||0);
    if(state.holdingsSort==='daily')return (n(b.newestIncome)||0)-(n(a.newestIncome)||0);
    if(state.holdingsSort==='weight')return (n(b.totalAmount)||0)-(n(a.totalAmount)||0);
    return (n(b.totalAmount)||0)-(n(a.totalAmount)||0);
  });
  const visible=rows.filter(f=>`${f.fundName||''} ${f.fundCode||''}`.toLowerCase().includes(state.holdingsSearch.toLowerCase())),cards=visible.map(f=>{
    const code=String(f.fundCode||''),name=String(f.fundName||code),amount=n(f.totalAmount),weight=n(totalAmount)>0&&amount!==null?amount/n(totalAmount)*100:null,pending=f.holdVol==='待确认',active=code===state.selectedHoldingCode;
    return `<button type="button" class="holding-fund-card ${active?'active':''}" data-holding-select="${esc(code)}" data-holding-search="${esc(`${name} ${code}`.toLowerCase())}" aria-pressed="${active}"><span class="holding-fund-card-head"><span><strong>${esc(name)}</strong><small>${esc(code)}</small></span><b>${money(amount)}</b></span><span class="holding-fund-card-meta"><span>日收益 <b class="${tone(f.newestIncome)}">${signed(f.newestIncome)}</b></span><span>累计 <b class="${tone(f.holdIncome)}">${signed(f.holdIncome)}</b></span><span>${weight===null?'—':num(weight)+'%'}</span></span><span class="holding-status ${pending?'pending':'confirmed'}">${pending?'份额待确认':'已确认持仓'}</span></button>`
  }).join('');
  const selected=rows.find(f=>String(f.fundCode||'')===state.selectedHoldingCode)||rows[0];
  return `<section class="holdings-list-section"><div class="holdings-list-head"><div><h2>持仓基金 <span>${funds.length} 只</span></h2></div><div class="holdings-list-tools"><label class="holdings-search"><span>⌕</span><input id="holdings-search" type="search" value="${esc(state.holdingsSearch)}" placeholder="搜索基金名称或代码" autocomplete="off"></label><label class="holdings-sort-label">排序<select id="holdings-sort"><option value="amount" ${state.holdingsSort==='amount'?'selected':''}>持有金额</option><option value="income" ${state.holdingsSort==='income'?'selected':''}>累计收益</option><option value="daily" ${state.holdingsSort==='daily'?'selected':''}>最新日收益</option><option value="weight" ${state.holdingsSort==='weight'?'selected':''}>组合占比</option></select></label></div></div><div class="holdings-split"><nav class="holdings-fund-list" aria-label="持仓基金列表">${cards||`<div class="holdings-empty">${funds.length?'没有找到匹配的基金。':'当前账户没有基金持仓。'}</div>`}<div id="holdings-filter-empty" class="holdings-empty" hidden>没有找到匹配的基金。</div></nav><div class="holding-detail-pane">${selected?holdingDetail(selected):'<div class="holding-detail-placeholder">从左侧选择一只基金查看详情。</div>'}</div></div></section>`
}

function holdingsQuestionBox(){const prompts=['近期收益主要受哪些基金影响？','我的基金是否买重复了？','我想让持仓波动小一点。'];return `<div class="holdings-prompt-chips">${prompts.map(prompt=>`<button type="button" data-holdings-question="${esc(prompt)}">${esc(prompt)} ↗</button>`).join('')}</div>`}
function portfolioPanel(){
  const box=holdingsQuestionBox();
  const a=state.analysis||{},m=a.metrics||{},benchmarkReturn=n(a.benchmarkMetrics?.returnPct),simulatedAmount=n(a.simulationAmount),simulatedProfit=simulatedAmount!==null&&n(m.returnPct)!==null?simulatedAmount*n(m.returnPct)/100:null;
  const metrics=[['区间模拟收益率',state.analysis?pct(m.returnPct):'—',tone(m.returnPct)],['模拟盈亏',state.analysis?signed(simulatedProfit):'—',tone(simulatedProfit)],['超额收益率',benchmarkReturn!==null&&n(m.returnPct)!==null?pct(m.returnPct-benchmarkReturn):'—',tone(benchmarkReturn!==null&&n(m.returnPct)!==null?m.returnPct-benchmarkReturn:null)],['最大回撤',state.analysis&&n(m.maxDrawdownPct)!==null?num(m.maxDrawdownPct)+'%':'—',''],['年化波动',state.analysis&&n(m.volatilityPct)!==null?num(m.volatilityPct)+'%':'—',''],['夏普比率',state.analysis?num(m.sharpe):'—','']];
  const metricRow=`<div class="holdings-backtest-kpis">${metrics.map(([label,value,color])=>`<div><small>${label}</small><strong class="${color}">${value}</strong></div>`).join('')}</div>`;
  if(state.analysisError)return `<section class="holdings-backtest-card"><div class="holdings-card-head"><div><h2>组合历史模拟</h2><p>历史模拟，不代表账户实际收益</p></div><span class="holdings-data-pill">暂不可用</span></div>${metricRow}${box}<div class="holdings-analysis-error"><strong>暂时无法生成组合模拟</strong><p>${esc(state.analysisError)}</p><small>账户真实持仓仍可在“持仓列表”查看；数据恢复后点击刷新重试。</small></div></section>`;
  if(!state.analysis)return `<section class="holdings-backtest-card"><div class="holdings-card-head"><div><h2>组合历史模拟</h2><p>当前持仓按固定权重回看复权净值</p></div><span class="holdings-data-pill">计算中</span></div>${metricRow}${box}<div class="panda-loading holdings-analysis-loading"><i></i>正在读取已确认持仓的复权净值并计算组合模拟…</div></section>`;
  const aligned=alignComparison(a.history,a.benchmark),allocations=(a.allocations||[]).map(x=>`<div class="holding-allocation-row"><span>${esc(x.name)} <small>${x.funds} 只</small></span><strong>${num(x.percent)}%</strong><em><i style="width:${Math.max(0,Math.min(100,n(x.percent)||0))}%;background:${esc(x.color)}"></i></em></div>`).join(''),findings=(a.findings||[]).slice(0,4).map(x=>`<article class="holding-finding ${esc(x.tone||'info')}"><i></i><div><strong>${esc(x.title)}</strong><p>${esc(x.text)}</p></div></article>`).join(''),failureText=(a.failures||[]).length?`<div class="holdings-coverage-note">${(a.failures||[]).length} 只基金因净值数据不足或不可用，未纳入模拟：${(a.failures||[]).slice(0,3).map(f=>esc(`${f.name||f.code}（${f.reason}）`)).join('；')}${(a.failures||[]).length>3?'…':''}</div>`:'';
  return `<section class="holdings-backtest-card">
    <div class="holdings-card-head"><div><h2>组合历史模拟</h2><p>当前持仓按固定权重回看净值 · ${esc(a.history?.[0]?.date||'—')} 至 ${esc(a.asOf||'—')}</p></div><span class="holdings-data-pill">历史模拟</span></div>
    ${metricRow}${box}
    <div class="holdings-analysis-grid"><div class="holdings-chart-column"><div class="holdings-chart-head"><strong>组合净值变化</strong><span>${esc(a.history?.[0]?.date||'—')} — ${esc(a.asOf||'—')}</span></div><div class="panda-chart-wrap">${lineChart(aligned,Boolean(a.benchmark?.length))}<div class="panda-chart-legend"><span><i class="strategy"></i>当前组合模拟</span>${a.benchmark?.length?'<span><i class="dash"></i>沪深300比较基准</span>':''}</div></div><small class="holdings-chart-note">${n(a.dataCoveragePct)===null?'':`模拟净值覆盖已确认持仓 ${num(a.dataCoveragePct)}%。`} ${benchmarkReturn===null?'没有可比基准数据。':`比较基准区间收益 ${pct(benchmarkReturn)}。`}</small></div><div class="holdings-analysis-side"><div class="holdings-findings"><div class="holdings-subhead"><strong>组合检查</strong><small>基于当前可用账户与净值数据</small></div>${findings||'<p class="holdings-muted">暂无可展示的组合检查结果。</p>'}</div><div class="holdings-allocation"><div class="holdings-subhead"><strong>持仓分类</strong><small>按基金名称粗略归类</small></div>${allocations||'<p class="holdings-muted">暂无分类数据。</p>'}</div></div></div>
    ${failureText}<p class="panda-essential-note">按当前权重模拟历史表现，非账户实际收益；不含历史申赎现金流、个人费率与税费。</p>${disclosure('模拟口径与来源',`<p>${esc(a.method||'')} 来源：${esc(a.source||'')}。模拟盈亏 = 当前可用模拟金额 × 区间收益率。</p>`)}
  </section>`
}
function orderDate(value){const match=String(value||'').match(/(\d{4})[-/]?(\d{2})[-/]?(\d{2})/);return match?`${match[1]}-${match[2]}-${match[3]}`:''}
function orderSide(row){const type=`${row.type||''} ${row.subtype||''}`;if(/赎回|卖出|转出/.test(type))return 'sell';if(/申购|定投|买入|认购|转入/.test(type))return 'buy';return ''}
function holdingTrades(detail){return (detail?.history?.orders||[]).map(row=>{const confirmed=n(row.confirmedAmount),applied=n(row.amount);return {date:orderDate(row.confirmedAt||row.acceptedAt),side:orderSide(row),amount:confirmed!==null&&confirmed>0?confirmed:applied,type:row.subtype||row.type||'交易',status:row.status||'状态待核实'}}).filter(row=>row.date&&row.side&&/确认成功|部分确认/.test(row.status)&&row.amount!==null).sort((a,b)=>a.date.localeCompare(b.date))}
function holdingDetail(fund){
  const code=String(fund.fundCode||''),name=String(fund.fundName||code),detail=state.holdingDetails[code]||{},trades=holdingTrades(detail),buys=trades.filter(x=>x.side==='buy').reduce((sum,x)=>sum+x.amount,0),sells=trades.filter(x=>x.side==='sell').reduce((sum,x)=>sum+x.amount,0),pending=fund.holdVol==='待确认';
  const metrics=[['当前持有市值',money(fund.totalAmount)],['累计持有收益',signed(fund.holdIncome),tone(fund.holdIncome)],['持有收益率',fund.holdIncomeRate&&fund.holdIncomeRate!=='-'?String(fund.holdIncomeRate):'—',tone(fund.holdIncomeRate)],['最新日收益',signed(fund.newestIncome),tone(fund.newestIncome)]];
  const chart=detail.nav?`<div class="holding-detail-chart"><div class="holding-detail-subhead"><strong>基金复权净值走势 · 近五年</strong><small>截至 ${esc(detail.nav.dataAsOf||'—')}</small></div><div class="panda-chart-wrap">${lineChart(detail.nav.points,false,trades)}<div class="panda-chart-legend"><span><i class="strategy"></i>区间复权净值变化</span><span><i class="buy"></i>申购 / 买入</span><span><i class="sell"></i>赎回 / 转出</span></div></div><small class="holdings-chart-note">展示基金净值相对区间变化，不代表个人账户收益；交易点按确认/受理日期映射到最近净值日。</small></div>`:detail.navError?`<div class="holding-detail-unavailable"><strong>基金净值走势暂不可用</strong><small>${esc(detail.navError)}</small></div>`:`<div class="holding-detail-unavailable"><strong>${detail.loading?'正在读取基金复权净值…':'等待基金走势数据'}</strong><small>数据源：扶摇 Fuyao</small></div>`;
  const tradeRows=trades.slice().reverse().slice(0,12).map(x=>`<tr><td>${esc(x.date)}</td><td><span class="trade-${x.side}">${x.side==='buy'?'申购 / 买入':'赎回 / 转出'}</span></td><td>${money(x.amount)}</td><td>${esc(x.status)}</td></tr>`).join('');
  const history=detail.historyError?`<div class="holding-detail-unavailable"><strong>交易记录暂不可用</strong><small>${esc(detail.historyError)}</small></div>`:detail.loading&&!detail.history?`<div class="holding-detail-unavailable"><strong>正在读取近五年交易记录…</strong><small>只读查询已确认的申购、买入、赎回和转出记录。</small></div>`:`<div class="holding-trade-section"><div class="holding-detail-subhead"><strong>近五年已确认交易</strong><small>${trades.length} 笔${detail.history?.period?` · ${esc(detail.history.period.start)} 至 ${esc(detail.history.period.end)}`:''}</small></div>${tradeRows?`<div class="holding-trade-table-wrap"><table class="holding-trade-table"><thead><tr><th>日期</th><th>方向</th><th>确认金额</th><th>状态</th></tr></thead><tbody>${tradeRows}</tbody></table></div>`:'<p class="holdings-muted">近五年没有返回可用于标点的已确认买卖记录；这不代表更早时期没有交易。</p>'}${detail.history?.truncated?'<small class="holdings-chart-note">记录条数达到查询上限，以上为近五年部分历史。</small>':''}</div>`;
  return `<section class="holding-detail"><header class="holding-detail-head"><div><h3>${esc(name)}</h3><p>${esc(code)} · <span class="holding-status ${pending?'pending':'confirmed'}">${pending?'份额待确认':'已确认持仓'}</span></p></div><button type="button" class="holding-detail-refresh" data-action="refresh-holding-detail" data-code="${esc(code)}">刷新详情</button></header><div class="holding-detail-kpis">${metrics.map(([label,value,color=''])=>`<div><small>${label}</small><strong class="${color}">${value}</strong></div>`).join('')}</div><details class="panda-disclosure"><summary>份额与历史交易汇总</summary><div class="holding-history-kpis"><span>近五年申购 / 买入 <b>${money(buys)}</b></span><span>近五年赎回 / 转出 <b>${money(sells)}</b></span><span>当前份额 <b>${pending?'待确认':(n(fund.holdVol)===null?esc(fund.holdVol||'—'):num(fund.holdVol))}</b></span></div></details><div class="holdings-tabbar" role="tablist" aria-label="基金详情"><button type="button" role="tab" aria-selected="${state.holdingDetailTab!=='trades'}" data-fund-tab="chart">走势</button><button type="button" role="tab" aria-selected="${state.holdingDetailTab==='trades'}" data-fund-tab="trades">交易</button></div>${state.holdingDetailTab==='trades'?history:chart}<div class="holdings-method-note">账户持有收益、收益率与份额来自同花顺爱基金；净值曲线来自扶摇 Fuyao。历史交易只列出查询区间内已确认记录。</div></section>`
}
function alignComparison(primary,comparison){const bench=(comparison||[]).slice().sort((a,b)=>String(a.date).localeCompare(String(b.date)));let cursor=-1,current=null;return (primary||[]).map(row=>{while(cursor+1<bench.length&&String(bench[cursor+1].date)<=String(row.date)){cursor++;current=bench[cursor]}return {date:row.date,value:row.value,benchmark:current?.value??null}})}
function watchlistPage(){const candidates=knownFunds();return `${heading('','我的自选','收藏想继续研究的基金。')}<form id="watch-form" class="panda-inline-form"><input name="query" aria-label="基金名称或代码" list="watch-candidates" placeholder="输入 6 位代码，或选择已有基金" required autocomplete="off"><datalist id="watch-candidates">${candidates.map(x=>`<option value="${esc(x.code)}">${esc(x.name)}</option>`).join('')}</datalist><button class="panda-button primary">添加</button></form><div class="panda-holding-list">${state.watchlist.map(x=>`<div class="panda-watch-row"><button data-action="drill-fund" data-code="${esc(x.code)}"><span><strong>${esc(x.name||x.code)}</strong><small>${esc(x.code)}</small></span></button><div>${button('选策略','pick-for-strategy',`data-code="${esc(x.code)}"`,'quiet')}${button('移除','remove-watch',`data-code="${esc(x.code)}"`,'quiet')}</div></div>`).join('')||'<div class="panda-plan-empty">添加第一只想研究的基金。</div>'}</div>`}
function knownFunds(){const rows=[...state.catalog.flatMap(x=>x.showcaseCandidates||[]),...state.watchlist,...(state.holdings?.funds||[]).map(x=>({code:x.fundCode,name:x.fundName}))];return [...new Map(rows.filter(x=>x.code).map(x=>[x.code,x])).values()]}
async function addWatch(form){const query=String(new FormData(form).get('query')||'').trim(),known=knownFunds().filter(x=>x.code===query||x.name===query);if(!/^\d{6}$/.test(query)&&known.length!==1)throw new Error('名称仅支持已载入的基金，请选择候选项或输入 6 位基金代码。');const code=known[0]?.code||query;const fund=known[0]||await api('/api/fund/nav?code='+encodeURIComponent(code));const b=await api('/api/watchlist',{code,name:fund.name||code});state.watchlist=b.watchlist||[];render()}
function planCards(){return state.plans.map(plan=>{const signal=plan.latestSignal,label={draft:'未开启',active:'跟踪中',paused:'已暂停',archived:'已归档'}[plan.status]||plan.status,run=state.runs.find(x=>x.id===plan.backtestRunId),perf=plan.performance||(run?{totalInvested:run.cashFlow?.totalInvested,netProfit:run.cashFlow?.netProfit,returnPct:run.metrics?.absoluteReturnPct??run.metrics?.returnPct,benchmarkReturnPct:run.metrics?.benchmarkReturnPct,excessReturnPct:run.metrics?.excessReturnPct,dataAsOf:run.dataAsOf}:null),rate=n(perf?.returnPct),attrs=`data-id="${esc(plan.id)}"`,action=plan.status==='draft'?button('开启跟踪','plan-action',attrs+' data-plan-action="enable"','primary'):plan.status==='active'?button('检查信号','plan-action',attrs+' data-plan-action="check"','primary'):plan.status==='paused'?button('恢复跟踪','plan-action',attrs+' data-plan-action="enable"','primary'):'';return `<article class="panda-plan-card"><div class="panda-plan-main"><div class="panda-plan-title"><strong>${esc(plan.name)}</strong><span class="panda-plan-status ${esc(plan.status)}">${label}</span></div><p>${esc(plan.fundCode||'固定行业基金池')}</p><small>${plan.lastCheckedAt?'最近检查 '+esc(dt(plan.lastCheckedAt)):'尚未检查'}</small></div><div class="panda-plan-signal"><strong>${esc(signal?.status==='ok'?(signal.state||'信号状态缺失'):signal?'暂无法判断':plan.status==='draft'?'等待开启跟踪':'尚无检查结果')}</strong><small>信号数据 ${esc(signal?.dataAsOf||'—')}</small>${disclosure('查看依据',esc(signal?.reason||(signal?.missingData||[]).join('；')||'开启跟踪后检查最新数据。'))}</div><div class="panda-plan-actions">${action}<details class="panda-menu"><summary aria-label="计划更多操作">⋯</summary><div>${plan.backtestRunId?button('回看回测','open-run',`data-id="${esc(plan.backtestRunId)}"`,'quiet'):''}${button('分享','share-plan',attrs,'quiet')}${plan.status==='active'?button('暂停跟踪','plan-action',attrs+' data-plan-action="pause"','quiet'):''}${plan.status!=='archived'?button('归档','plan-action',attrs+' data-plan-action="archive"','quiet'):''}</div></details></div><div class="panda-plan-performance"><div class="panda-plan-performance-head"><small>关联回测 · 非账户实际收益</small><span>截至 ${esc(perf?.dataAsOf||plan.backtestDataAsOf||'—')}</span></div><div class="panda-plan-kpis"><span>模拟投入 <b>${money(perf?.totalInvested)}</b></span><span>模拟收益 <b class="${tone(perf?.netProfit)}">${signed(perf?.netProfit)}</b></span><span>策略收益 <b class="${tone(rate)}">${pct(rate)}</b></span><span>超额收益 <b class="${tone(perf?.excessReturnPct)}">${pct(perf?.excessReturnPct)}</b></span></div>${disclosure('比较基准',`<p>同期基准收益 <b class="${tone(perf?.benchmarkReturnPct)}">${pct(perf?.benchmarkReturnPct)}</b> · ${esc(perf?.formula||'超额收益 = 策略同期累计收益率 - 同期基准收益率')}</p>`)}</div></article>`}).join('')||`<div class="panda-plan-empty"><p>找到合适的策略后，可从回测结果保存计划。</p><button class="panda-button primary" data-nav="library">去看策略</button></div>`}
function plansPage(){return `${heading('','我的计划',state.planPerformanceLoading?'正在更新回测指标…':'开启跟踪后，应用运行期间每 30 分钟检查一次。')}<div class="panda-plan-list">${planCards()}</div>`}
function historyPage(){return `${heading('','回测记录','点击记录，回看当时的结果与配置。')}<div class="panda-history-list">${state.runs.slice().reverse().map(run=>{const value=run.metrics?.absoluteReturnPct??run.metrics?.returnPct;return `<button class="panda-run-card" data-action="open-run" data-id="${esc(run.id)}"><div><strong>${esc(findStrategy(run.strategyId)?.name||run.strategyId)}</strong><small>${esc(run.fundCode||'固定行业基金池')} · ${esc(dt(run.createdAt))}</small></div><div class="panda-run-result"><small>策略累计收益</small><strong class="${tone(value)}">${run.status==='ok'?pct(value):'数据不完整'}</strong></div><span>→</span></button>`}).join('')||'<div class="panda-plan-empty">完成一次回测后，结果会保存在这里。</div>'}</div>`}
function accountPage(){const connected=Boolean(state.holdings),disabled=state.accountBusy?'disabled':'';return `${heading('','连接与设置','配置账户与模型，开始研究。')}<div class="panda-connect-grid"><section><h2>同花顺账户</h2><p>${state.accountBusy?'等待扫码确认…':connected?'已连接 · 仅查询持仓与订单':'尚未连接'}</p>${button(connected?'切换账户':'扫码连接',connected?'switch-account':'login-fund',disabled,'primary')}${connected?button('刷新','refresh-holdings',disabled,'quiet'):''}${state.holdingsError?disclosure('连接详情',esc(state.holdingsError)):''}${disclosure('授权范围','<p>查询持仓和订单。实际交易由你在同花顺 App 完成；切换账户将替换本机授权。</p>')}</section><section><h2>对话模型</h2><p>${esc(D.current?.model||D.settings?.subscriptionModel||'桌面端配置后使用')}</p><button class="panda-button" data-nav="settings">模型设置</button><p class="panda-section-caption">模型与思考强度用于新会话。</p></section></div>`}
function modelRows(){const value=D.status?.models;return Array.isArray(value?.data)?value.data:Array.isArray(value?.models)?value.models:[]}
function settingsPage(){if(!D.enabled)return `${heading('MODEL SETTINGS','模型与推理设置','真实模型设置只在 Electron 桌面应用中提供。')}<div class="panda-result-blocked"><b>!</b><div><strong>当前是浏览器模式</strong><p>请运行 npm start 或 start-panda-strategy.ps1 使用持续会话、模型选择、思考强度和工具进度。</p></div></div>`;const models=modelRows(),settings=D.settings||{},selected=settings.subscriptionModel||'gpt-6-astra',model=models.find(x=>x.id===selected),efforts=(model?.supportedReasoningEfforts||[]).map(x=>typeof x==='string'?x:x?.reasoningEffort).filter(Boolean);return `${heading('','模型设置','仅影响新会话；已有会话保持原设置。')}<form id="model-form" class="panda-settings-card"><div class="panda-field"><label>模型</label><select name="model">${(models.length?models:[{id:selected,displayName:selected}]).map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.displayName||x.id)}</option>`).join('')}</select></div><div class="panda-field"><label>思考强度</label><select name="effort">${(efforts.length?efforts:['low','medium','high','xhigh']).map(x=>`<option value="${x}" ${x===settings.subscriptionEffort?'selected':''}>${esc(({low:'低',medium:'中',high:'高',xhigh:'很高',max:'最高',ultra:'超高'})[x]||x)}</option>`).join('')}</select></div><div class="panda-detail-actions"><button class="panda-button primary">保存到新会话</button></div></form>`}

function render(){captureParameterDraft();const focused=document.activeElement,focusName=focused?.closest?.('#panda-strategy-form')?focused.name:null,content=$('#panda-content'),shell=$('#agent-shell');if(shell&&content.contains(shell))$('#agent-panel').append(shell);let html;if(state.selected)html=detail(findStrategy(state.selected));else html=({workbench:home,library,holdings:holdingsPage,watchlist:watchlistPage,plans:plansPage,history:historyPage,account:accountPage,settings:settingsPage}[state.nav]||home)();content.innerHTML=html;document.querySelectorAll('.panda-sidebar [data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===state.nav));$('#panda-data-status').textContent=state.holdings?'账户已连接':'账户未连接';$('#panda-page-title').textContent=state.selected?'策略详情':titles[state.nav];ensureChrome();placeAgent();renderSessions();if(focusName)Array.from($('#panda-strategy-form')?.elements||[]).find(x=>x.name===focusName)?.focus();if(state.nav==='holdings'&&!state.holdings&&!state.holdingsError)loadHoldings()}
function captureParameterDraft(){if(state.skipDraftCapture){state.skipDraftCapture=false;return}const form=$('#panda-strategy-form');if(!state.paramEditing||form?.dataset.editing!=='true')return;const item=findStrategy(state.selected);if(!item)return;const raw=Object.fromEntries(new FormData(form));state.paramDraft={code:raw.code||'',params:Object.fromEntries((item.params||[]).map(x=>[x.key,raw['param-'+x.key]??x.default]))}}
function openWorkbench(prompt='',context=null){if(D.running){toast('请先等待当前对话完成或停止任务。');return}state.backtestRevision++;state.busy=false;state.composerContext=context;state.nav='workbench';state.selected=null;state.paramEditing=false;state.paramDraft=null;state.holdingsAgentOpen=false;state.agentOpen=false;render();const input=$('#agent-input');if(input){input.value=prompt;input.focus()}}
function ensureChrome(){if(!$('#panda-toast'))document.body.insertAdjacentHTML('beforeend','<div id="panda-toast" class="panda-toast"></div>')}
function placeAgent(){const shell=$('#agent-shell'),panel=$('#agent-panel'),conversationHost=$('#agent-conversation-host'),composerHost=$('#agent-composer-host');if(!shell||!panel)return;document.body.classList.remove('panda-agent-side','panda-holdings-agent-open','panda-conversation-active','panda-conversation-idle');panel.hidden=true;if(state.nav==='workbench'&&!state.selected&&(conversationHost||composerHost)){(conversationHost||composerHost).append(shell);document.body.classList.add(conversationHost?'panda-conversation-active':'panda-conversation-idle')}else panel.append(shell);renderAgentPanel()}
function textFromUserContent(content){return (content||[]).filter(x=>x.type==='text'&&!String(x.text||'').startsWith('[WORKBENCH_PAGE_CONTEXT]')).map(x=>x.text||'').join('\n')}
function reasoningText(item){for(const v of [item?.text,item?.summaryText,item?.summary]){if(typeof v==='string'&&v.trim())return v;if(Array.isArray(v)){const t=v.map(x=>typeof x==='string'?x:x?.text||'').filter(Boolean).join('\n');if(t)return t}}return ''}
function planText(plan){const rows=Array.isArray(plan)?plan:Array.isArray(plan?.steps)?plan.steps:[];return rows.map(x=>`${x.status==='completed'?'✓':x.status==='inProgress'||x.status==='in_progress'?'◌':'○'} ${x.step||x.text||x.description||''}`).join('\n')}
function renderAgentItem(m){if(m.type==='tool')return `<div class="agent-tool ${m.status==='failed'?'error':''}"><span>${['inProgress','running'].includes(m.status)?'<i class="spinner"></i>':'◇'}</span><div><strong>${esc(toolLabel(m.tool))}</strong><small>${m.status==='completed'?'已完成':m.status==='failed'?'调用失败':'调用中'}</small></div></div>`;if(m.type==='reasoning')return `<details class="agent-reasoning" data-disclosure="${esc(m.id)}"><summary>${m.streaming?'正在思考':'思考摘要'}</summary><div>${renderMarkdown(m.text)}</div></details>`;if(m.type==='plan')return `<details class="agent-reasoning" data-disclosure="${esc(m.id)}"><summary>执行步骤</summary><div>${renderMarkdown(m.text)}</div></details>`;return `<div class="agent-message ${m.role} ${m.error?'error':''}"><small>${m.role==='user'?'你':'同花顺理财'}</small><div>${m.role==='assistant'?renderMarkdown(m.text):esc(m.text).replaceAll('\n','<br>')}</div></div>`}
function renderAgentMessages(){let out='',group=[];const flush=()=>{if(!group.length)return;const failed=group.some(x=>x.status==='failed');out+=`<details class="agent-process ${failed?'error':''}" data-disclosure="process-${esc(group[0].id)}" ${failed?'open':''}><summary>${failed?'工具执行有异常':'研究过程'} · ${group.filter(x=>x.type==='tool').length} 次工具调用</summary>${group.map(renderAgentItem).join('')}</details>`;group=[]};for(const row of D.messages){if(row.type)group.push(row);else{flush();out+=renderAgentItem(row)}}flush();return out}
function agentProgressMarkup(){if(D.pendingInput)return '<div class="agent-progress-track waiting"><span class="current">等待你补充信息</span></div>';if(!D.running)return '';const current=D.messages.slice(D.turnMessageStart||0),tool=current.findLast(x=>x.type==='tool'&&['inProgress','running'].includes(x.status)),answer=current.some(x=>x.role==='assistant'&&x.text),stage=tool?toolLabel(tool.tool):answer?'正在整理回答':'正在分析问题',elapsed=D.turnStartedAt?Math.max(0,Math.floor((Date.now()-D.turnStartedAt)/1000)):0;return `<div class="agent-progress-track"><i class="spinner"></i><span class="current">${esc(stage)}</span><em id="agent-elapsed">${elapsed} 秒</em></div>`}
function toolLabel(name){return ({get_dashboard:'读取工作台摘要',get_buy_preview:'查询申购规则',get_redeem_preview:'查询赎回条件',get_order:'读取订单详情',get_connection_status:'读取连接状态',list_investment_strategies:'读取投资策略目录',run_investment_backtest:'运行真实策略回测',save_strategy_variant:'保存策略版本',get_account_brief:'读取账户简报',list_holdings:'读取真实持仓',analyze_portfolio:'分析持仓归因',list_orders:'查询真实订单',list_watchlist:'读取自选基金',set_watchlist:'更新自选基金',get_fund_accounts:'读取基金账户'})[name]||name||'基金工具'}
function renderSessions(){const host=$('#panda-sessions');if(!host)return;host.innerHTML=D.enabled?(D.sessions.map(s=>`<div class="panda-session-row ${s.threadId===D.current?.threadId?'active':''}"><button data-session="${esc(s.threadId)}" ${D.running?'disabled':''}><strong title="${esc((s.model||'')+' · '+dt(s.updatedAt))}">${s.pinned?'★ ':''}${esc(s.title)}</strong></button><button data-session-pin="${esc(s.threadId)}" title="${s.pinned?'取消置顶':'置顶'}" ${D.running?'disabled':''}>${s.pinned?'★':'☆'}</button><button data-session-delete="${esc(s.threadId)}" title="删除对话" ${D.running?'disabled':''}>×</button></div>`).join('')||'<span>还没有会话</span>'):'<span>浏览器模式不启动模型会话</span>'}
function renderAgentQuestion(){const host=$('#agent-question');if(!host)return;const request=D.pendingInput;if(!request){host.hidden=true;host.innerHTML='';return}host.hidden=false;host.innerHTML=`<form id="agent-question-form"><strong>Agent 需要你补充信息</strong>${(request.questions||[]).map((q,i)=>{const opts=(q.options||[]).map((o,j)=>`<label><input type="radio" name="answer-${i}" value="${esc(o.label)}" ${j===0?'required':''}><span><b>${esc(o.label)}</b><small>${esc(o.description||'')}</small></span></label>`).join('');return `<fieldset data-id="${esc(q.id)}"><legend>${esc(q.header||'请确认')}</legend><p>${esc(q.question)}</p>${opts||`<input name="answer-${i}" required>`}</fieldset>`}).join('')}<button class="panda-button primary">提交回答</button></form>`}
function renderAgentPanel(){const input=$('#agent-input'),messages=$('#agent-messages');if(!D.enabled){$('#agent-provider').textContent='浏览器预览';$('#agent-status').textContent='对话请使用桌面应用';if(input)input.disabled=true;$('#agent-send').disabled=true;return}const model=D.current?.model||D.settings?.subscriptionModel||'正在连接模型',effort=D.current?.effort||D.settings?.subscriptionEffort||'',effortLabel=({low:'低',medium:'中',high:'高',xhigh:'很高',max:'最高',ultra:'超高'})[effort]||effort;$('#agent-provider').textContent=model;$('#agent-session-title').textContent=D.current?.title||'基金研究';$('#agent-model-setting').textContent=model+(effortLabel?' · '+effortLabel:'');$('#agent-model-setting').title='模型与思考强度；在设置中修改后用于新会话';$('#agent-status').innerHTML=agentProgressMarkup();$('#agent-status').hidden=!D.running&&!D.pendingInput;const opened=new Set(Array.from(messages.querySelectorAll('details[open][data-disclosure]')).map(x=>x.dataset.disclosure)),nearBottom=messages.scrollHeight-messages.scrollTop-messages.clientHeight<100,scrollTop=messages.scrollTop;messages.innerHTML=renderAgentMessages();messages.querySelectorAll('details[data-disclosure]').forEach(x=>{if(opened.has(x.dataset.disclosure))x.open=true});const context=$('#agent-context-chip');context.hidden=!state.composerContext;context.innerHTML=state.composerContext?`<span>已附带：${esc(state.composerContext.pageTitle||'页面摘要')}</span><button type="button" data-action="clear-agent-context" aria-label="移除页面摘要">×</button>`:'';renderAgentQuestion();$('#agent-run-state').textContent='';$('#agent-stop').hidden=!D.running;$('#agent-send').disabled=D.running;input.disabled=D.running;$('#agent-pin').textContent=D.current?.pinned?'取消置顶':'置顶';for(const id of ['agent-pin','agent-rename','agent-archive','agent-delete'])$('#'+id).disabled=!D.current||D.running;requestAnimationFrame(()=>{messages.scrollTop=nearBottom?messages.scrollHeight:scrollTop})}
function hydrateThread(thread){D.messages=[];D.tools.clear();D.pendingInput=null;for(const turn of thread?.turns||[])for(const item of turn.items||[]){if(item.type==='userMessage')D.messages.push({id:item.id,role:'user',text:textFromUserContent(item.content)});else if(item.type==='agentMessage'&&item.text&&!/^Reconnecting/.test(item.text))D.messages.push({id:item.id,role:'assistant',text:item.text});else if(item.type==='reasoning'&&reasoningText(item))D.messages.push({id:item.id,type:'reasoning',text:reasoningText(item)});else if(item.type==='mcpToolCall'){const row={id:item.id,type:'tool',tool:item.tool,status:item.status,error:item.error};D.messages.push(row);D.tools.set(item.id,row)}}renderAgentPanel()}
async function newSession(preservePage=false){const page=state.nav,selected=state.selected,r=await desktopCall(window.fundDesktop.newSession());D.current=r.session;D.messages=[];D.tools.clear();D.pendingInput=null;if(!preservePage)state.composerContext=null;D.sessions=await desktopCall(window.fundDesktop.listSessions());if(preservePage){state.nav=page;state.selected=selected}else{state.nav='workbench';state.selected=null}render();$('#agent-input')?.focus()}
async function resumeSession(id){const r=await desktopCall(window.fundDesktop.resumeSession(id));state.composerContext=null;if(r.stale){D.sessions=r.sessions||[];D.current=null;D.messages=[];render();return}D.current=r.session;hydrateThread(r.thread);renderSessions();renderAgentPanel()}
function pageContext(){
  const route=state.selected?'strategy-detail':state.nav;
  const context={route,pageTitle:state.selected?'策略详情':titles[state.nav]||'策略详情'};
  const metricSummary=source=>{const out={};for(const key of ['returnPct','absoluteReturnPct','excessReturnPct','benchmarkReturnPct','maxDrawdownPct','volatilityPct','annualizedReturnPct','sharpe','sortino','winRatePct','tradeCount','dataCoveragePct']){const value=n(source?.[key]);if(value!==null)out[key]=value}return out};
  const resultSummary=result=>({
    id:String(result?.runId||''),status:String(result?.status||''),fundCode:String(result?.fundCode||''),
    dataAsOf:String(result?.dataAsOf||''),source:String(result?.source||''),benchmarkName:String(result?.benchmarkName||''),
    periodStart:String(result?.period?.start||''),periodEnd:String(result?.period?.end||result?.dataAsOf||''),
    metrics:metricSummary(result?.metrics),parameters:result?.parameters||{},
    totalInvested:n(result?.cashFlow?.totalInvested),netProfit:n(result?.cashFlow?.netProfit),
    missingData:Array.isArray(result?.missingData)?result.missingData.slice(0,10):[]
  });
  const strategySummary=item=>{const best=showcaseBest(item);return {
    id:item.id,name:currentVariant(item.id)?.name||item.name,version:item.version,category:item.category,
    fundCode:best?.fundCode||'',dataAsOf:best?.dataAsOf||'',metrics:metricSummary(best?.metrics)
  }};
  const runSummary=run=>{
    const result=run.result||run;
    return {...resultSummary(result),id:String(run.id||result.runId||''),strategyId:String(run.strategyId||result.strategyId||''),
      strategyName:findStrategy(run.strategyId)?.name||String(run.strategyId||''),version:String(run.strategyVersion||result.strategyVersion||''),
      status:String(run.status||result.status||''),dataAsOf:String(run.dataAsOf||result.dataAsOf||''),
      fundCode:String(run.fundCode||result.fundCode||''),parameters:result.parameters||run.parameters||{},
      metrics:metricSummary(result.metrics||run.metrics),missingData:run.missingData||result.missingData||[],
      totalInvested:n(result.cashFlow?.totalInvested??run.cashFlow?.totalInvested),netProfit:n(result.cashFlow?.netProfit??run.cashFlow?.netProfit)};
  };
  const drillOpen=Boolean((($('#panda-dialog')?.open)||state.agentPageFocus==='fund')&&state.drill);
  if(state.selected){
    const item=findStrategy(state.selected);
    if(item){
      const variant=currentVariant(item.id);
      const form=$('#panda-strategy-form'),raw=state.paramEditing&&form?Object.fromEntries(new FormData(form)):null;
      const editedParams=raw?Object.fromEntries((item.params||[]).filter(spec=>raw['param-'+spec.key]!==undefined).map(spec=>{const value=raw['param-'+spec.key];return [spec.key,spec.choices?value:(String(value).trim()&&Number.isFinite(Number(value))?Number(value):null)]})):null;
      context.strategy={id:item.id,name:item.name,version:item.version,tab:state.detailTab,
        variantName:raw?.name||variant?.name||'',fundCode:raw&&raw.code!==undefined?raw.code:state.result?.fundCode||variant?.fundCode||state.pendingCode||item.defaultFundCode||'',
        params:editedParams||state.result?.parameters||variant?.params||item.defaultParams||{},unsavedChanges:Boolean(raw)};
    }
    if(state.result)context.backtest=resultSummary(state.result);
  }
  if(state.nav==='holdings'){
    context.tab=state.holdingsTab||'list';
    context.filter=state.holdingsSearch||'';
    context.sort=state.holdingsSort||'amount';
    if(state.holdingsAgentContext)context.holdingsDiagnosis=state.holdingsAgentContext;
    if(state.holdings){
      const funds=state.holdings.funds||[],summary=state.holdings.summary||{},performance=holdingPerformance(funds,summary),total=n(summary.totalAmount);
      const selected=funds.find(f=>String(f.fundCode||'')===state.selectedHoldingCode)||null;
      const detail=selected?state.holdingDetails[String(selected.fundCode||'')]:null;
      const points=detail?.nav?.points||[];
      context.holdingsSnapshot={
        asOf:state.holdings.fetchedAt,source:state.holdings.source||'同花顺爱基金 · thsfund',
        summary:{totalAmount:n(summary.totalAmount),confirmedAmount:n(summary.confirmedAmount),pendingAmount:n(summary.pendingAmount),pendingCount:n(summary.pendingCount),holdingIncome:performance.holdingIncome,latestDailyIncome:performance.latestIncome,latestDailyRatePct:performance.dailyRate,latestDailyCoverage:`${performance.dailyCount}/${performance.confirmedCount}`},
        funds:funds.slice(0,50).map(f=>({code:String(f.fundCode||''),name:String(f.fundName||''),amount:n(f.totalAmount),weightPct:total&&total>0&&n(f.totalAmount)!==null?n(f.totalAmount)/total*100:null,holdingIncome:n(f.holdIncome),holdingIncomeRate:String(f.holdIncomeRate||''),latestIncome:n(f.newestIncome),shareStatus:f.holdVol==='待确认'?'待确认':'已确认'})),
        selectedFund:selected?{code:String(selected.fundCode||''),name:String(selected.fundName||'')}:null,
        selectedDetail:selected?{code:String(selected.fundCode||''),nav:detail?.nav?{dataAsOf:detail.nav.dataAsOf,pointCount:points.length,periodStart:points[0]?.date||'',periodEnd:points.at(-1)?.date||''}:null,trades:holdingTrades(detail).slice(-30)}:null,
        simulation:state.analysis?{label:'当前权重历史模拟，不是账户实际收益',periodStart:state.analysis.history?.[0]?.date||null,periodEnd:state.analysis.asOf||null,returnPct:n(state.analysis.metrics?.returnPct),maxDrawdownPct:n(state.analysis.metrics?.maxDrawdownPct),volatilityPct:n(state.analysis.metrics?.volatilityPct),sharpe:n(state.analysis.metrics?.sharpe),benchmarkReturnPct:n(state.analysis.benchmarkMetrics?.returnPct),dataCoveragePct:n(state.analysis.dataCoveragePct),source:state.analysis.source||''}:null
      };
    }
  }
  if(drillOpen){const points=state.drill.points||[];context.selectedFund={code:state.drill.code,name:state.drill.name,dataAsOf:state.drill.dataAsOf||'',source:state.drill.source||'',manager:state.drill.manager||'',periodStart:points[0]?.date||'',periodEnd:points.at(-1)?.date||'',recentPoints:points.slice(-12).map(point=>({date:point.date,value:n(point.value)}))};}
  if(!state.selected&&!drillOpen){
    if(state.nav==='library')context.pageSnapshot={kind:'strategies',items:sortedStrategies().slice(0,20).map(strategySummary)};
    else if(state.nav==='watchlist')context.pageSnapshot={kind:'watchlist',items:state.watchlist.slice(0,30).map(row=>({code:String(row.code||''),name:String(row.name||'')}))};
    else if(state.nav==='plans')context.pageSnapshot={kind:'plans',items:state.plans.slice(0,30).map(plan=>{
      const run=state.runs.find(row=>row.id===plan.backtestRunId),performance=plan.performance||(run?{totalInvested:run.cashFlow?.totalInvested,netProfit:run.cashFlow?.netProfit,returnPct:run.metrics?.absoluteReturnPct??run.metrics?.returnPct,benchmarkReturnPct:run.metrics?.benchmarkReturnPct,excessReturnPct:run.metrics?.excessReturnPct,dataAsOf:run.dataAsOf}:null),signal=plan.latestSignal;
      return {name:plan.name,strategyId:plan.strategyId,strategyVersion:plan.strategyVersion,fundCode:plan.fundCode,status:plan.status,amount:n(plan.amount),budget:n(plan.budget),dataAsOf:plan.backtestDataAsOf||performance?.dataAsOf||'',signalStatus:signal?.status||'',signalState:signal?.state||'',signalAsOf:signal?.dataAsOf||'',metrics:metricSummary(performance)};
    })};
    else if(state.nav==='history'){
      const focused=state.runFocus&&state.runs.find(row=>row.id===state.runFocus);
      context.pageSnapshot={kind:focused?'backtest-detail':'history',items:(focused?[focused]:state.runs.slice().reverse().slice(0,20)).map(runSummary)};
    }else if(state.nav==='account'){
      context.pageSnapshot={kind:'account',connected:Boolean(state.holdings),loginInProgress:Boolean(state.accountBusy),holdingsCount:state.holdings?.funds?.length??null};
    }else if(state.nav==='settings'){
      const form=$('#model-form'),model=form?.elements?.model?.value||D.settings?.subscriptionModel||'',effort=form?.elements?.effort?.value||D.settings?.subscriptionEffort||'';
      context.pageSnapshot={kind:'settings',model,effort};
    }else if(state.nav==='workbench'&&!D.messages.length){
      context.pageSnapshot={kind:'workbench',summary:{strategyCount:state.catalog.length,watchlistCount:state.watchlist.length,activePlanCount:state.plans.filter(plan=>plan.status==='active').length,holdingsCount:state.holdings?.funds?.length??null},items:sortedStrategies().slice(0,8).map(strategySummary)};
    }
  }
  return context;
}
function onAgentEvent({method,params}){if(params?.threadId&&params.threadId!==D.current?.threadId)return;if(method==='turn/started'){D.running=true;D.turnStartedAt=D.turnStartedAt||Date.now()}else if(method==='turn/completed'){D.running=false;D.pendingInput=null;D.turnStartedAt=null;window.fundDesktop.listSessions().then(desktopCall).then(x=>{D.sessions=x;D.current=x.find(s=>s.threadId===D.current?.threadId)||D.current;renderSessions();renderAgentPanel()}).catch(()=>{})}else if(method==='item/tool/requestUserInput')D.pendingInput=params;else if(method==='item/tool/requestUserInput/resolved')D.pendingInput=null;else if(method==='item/agentMessage/delta'){let row=D.messages.find(x=>x.id===params.itemId);if(!row){row={id:params.itemId,role:'assistant',text:''};D.messages.push(row)}row.text+=params.delta||''}else if(method==='item/reasoning/summaryTextDelta'){let row=D.messages.find(x=>x.id===params.itemId);if(!row){row={id:params.itemId,type:'reasoning',text:'',streaming:true};D.messages.push(row)}row.text+=params.delta||''}else if(method==='item/completed'&&params.item?.type==='reasoning'){const text=reasoningText(params.item);let row=D.messages.find(x=>x.id===params.item.id);if(!row&&text)D.messages.push({id:params.item.id,type:'reasoning',text});else if(row){row.text=text||row.text;row.streaming=false}}else if(method==='turn/plan/updated'){let row=D.messages.find(x=>x.type==='plan'&&x.turnId===params.turnId);if(!row){row={id:'plan-'+Date.now(),turnId:params.turnId,type:'plan',text:planText(params.plan)};D.messages.push(row)}else row.text=planText(params.plan)}else if(method==='item/started'&&params.item?.type==='mcpToolCall'){const row={id:params.item.id,type:'tool',tool:params.item.tool,status:params.item.status};D.messages.push(row);D.tools.set(row.id,row)}else if(method==='item/completed'&&params.item?.type==='mcpToolCall'){const row=D.tools.get(params.item.id);if(row)Object.assign(row,{status:params.item.status,error:params.item.error})}else if(method==='item/completed'&&params.item?.type==='agentMessage'){let row=D.messages.find(x=>x.id===params.item.id);if(!row)D.messages.push({id:params.item.id,role:'assistant',text:params.item.text||''});else row.text=params.item.text||row.text}else if(method==='error'){D.running=false;D.turnStartedAt=null;D.messages.push({role:'assistant',text:params.error?.message||params.message||'Agent 运行失败。',error:true})}renderAgentPanel()}
async function sendAgent(text){
  if(!D.enabled){toast('真实 Agent 需要从桌面应用启动。');return}
  if(!text||D.running)return;
  const preservePage=Boolean(state.composerContext);
  const context=state.composerContext||pageContext();
  if(!D.current)await newSession(preservePage);
  const localId='local-'+Date.now();
  D.turnMessageStart=D.messages.length;D.tools.clear();D.messages.push({id:localId,role:'user',text});D.running=true;D.turnStartedAt=Date.now();render();
  try{
    await desktopCall(window.fundDesktop.sendMessage({threadId:D.current.threadId,text,pageContext:context}));
    state.holdingsAgentContext=null;state.composerContext=null;renderAgentPanel();if($('#agent-input'))$('#agent-input').value='';
  }catch(error){
    D.running=false;D.turnStartedAt=null;D.messages=D.messages.filter(row=>row.id!==localId);render();throw error;
  }
}
async function initDesktop(){if(!D.enabled)return;window.fundDesktop.onEvent(onAgentEvent);window.fundDesktop.onBusinessChanged(async()=>{await refreshLocal();render()});D.settings=await desktopCall(window.fundDesktop.getSettings());D.sessions=await desktopCall(window.fundDesktop.listSessions());try{D.status=await desktopCall(window.fundDesktop.getStatus())}catch(e){D.status={error:e.message}}D.initialized=true;render()}

async function loadHoldingDetail(code,force=false){if(!code)return;const current=state.holdingDetails[code];if(!force&&(current?.loaded||current?.loading))return;state.holdingDetails[code]={...(current||{}),loading:true};render();const [navResult,historyResult]=await Promise.allSettled([api('/api/fund/nav?code='+encodeURIComponent(code)+'&range=fyear'),api('/api/fund/trade-history?code='+encodeURIComponent(code))]);state.holdingDetails[code]={loaded:true,loading:false,nav:navResult.status==='fulfilled'?navResult.value:null,navError:navResult.status==='rejected'?navResult.reason.message:'',history:historyResult.status==='fulfilled'?historyResult.value:null,historyError:historyResult.status==='rejected'?historyResult.reason.message:''};render()}
async function loadHoldings(){state.holdingsError='';state.analysisError='';state.analysis=null;state.holdingDetails={};try{state.holdings=await api('/api/holdings');const funds=state.holdings.funds||[];if(!funds.some(f=>String(f.fundCode||'')===state.selectedHoldingCode))state.selectedHoldingCode=String((funds.find(f=>f.holdVol!=='待确认')||funds[0])?.fundCode||'');render();if(state.selectedHoldingCode)loadHoldingDetail(state.selectedHoldingCode);try{state.analysis=await api('/api/portfolio-analysis')}catch(e){state.analysisError=e.message}render()}catch(e){state.holdingsError=e.message;render()}}
async function askHoldingsAgent(question){openWorkbench(String(question||'请帮我分析当前持仓。'),pageContext())}
async function refreshLocal(){const b=await api('/api/bootstrap');state.csrf=b.csrf;state.catalog=b.strategyCatalog||[];state.plans=b.state?.strategyPlans||[];state.runs=b.state?.strategyRuns||[];state.events=b.state?.strategyEvents||[];state.variants=b.state?.strategyVariants||[];state.watchlist=b.state?.watchlist||[]}
async function loadShowcase(item){if(state.showcases[item.id])return state.showcases[item.id];if(showcasePromises.has(item.id))return showcasePromises.get(item.id);state.showcaseLoading.add(item.id);render();const promise=api('/api/strategy-invest/showcase',{strategyId:item.id}).then(async report=>{state.showcases[item.id]=report;state.runs=await api('/api/strategy-runs');return report}).finally(()=>{state.showcaseLoading.delete(item.id);showcasePromises.delete(item.id);render()});showcasePromises.set(item.id,promise);return promise}
async function loadShowcases(){for(const item of state.catalog){try{await loadShowcase(item)}catch(e){state.showcases[item.id]={status:'blocked',missingData:[e.message]}}}render()}
async function runBacktest(item,code,params,isDefault=false){const revision=++state.backtestRevision;state.busy=true;state.defaultLoading=isDefault?item.id:null;state.result=null;state.job={status:'running',stage:'queued',progress:1,logs:[{at:new Date().toISOString(),message:isDefault?'正在按策略卡相同参数准备默认回测。':'正在按当前参数准备回测。'}]};render();try{const created=await api('/api/strategy-invest/jobs',{strategyId:item.id,code:String(code||'').trim(),params});await pollJob(created.jobId,revision)}catch(e){if(revision!==state.backtestRevision)return;state.busy=false;state.defaultLoading=null;state.job={status:'failed',stage:'failed',progress:100,error:e.message,logs:[{at:new Date().toISOString(),message:e.message}]};render()}}
async function startBacktest(form,item){const {raw,params}=paramsFromForm(form,item);state.paramDraft={code:raw.code,params};state.paramEditing=false;await runBacktest(item,raw.code,params,false)}
async function openStrategy(id){const item=findStrategy(id);state.backtestRevision++;state.busy=false;state.skipDraftCapture=true;state.paramDraft=null;state.nav='library';state.selected=id;state.variant=null;state.result=null;state.job=null;state.detailTab='editor';state.paramEditing=false;state.paramsExpanded=false;state.defaultLoading=item.id;render();try{const report=await loadShowcase(item),best=report?.best||showcaseBest(item);if(state.selected!==id)return;state.defaultLoading=null;if(best?.status==='ok'){state.result=best;if(state.pendingCode&&item.codeRequired!==false){state.paramDraft={code:state.pendingCode,params:{...best.parameters}};state.paramEditing=true;state.pendingCode=''}render();return}state.result={status:'blocked',strategyId:item.id,strategyVersion:item.version,missingData:report?.missingData||['候选池没有通过数据校验的结果。'],source:item.dataBasis};render()}catch(e){state.defaultLoading=null;state.result={status:'blocked',strategyId:item.id,strategyVersion:item.version,missingData:[e.message],source:item.dataBasis};render()}}
async function pollJob(id,revision=state.backtestRevision){if(revision!==state.backtestRevision)return;clearTimeout(jobTimer);try{const job=await api('/api/strategy-invest/job?id='+encodeURIComponent(id));if(revision!==state.backtestRevision){if(job.status==='completed')state.runs=await api('/api/strategy-runs');return}state.job=job;if(job.status==='completed'){state.busy=false;state.defaultLoading=null;state.paramEditing=false;state.paramDraft=null;state.result=job.result;state.runs=await api('/api/strategy-runs');render();return}if(job.status==='failed'){state.busy=false;state.defaultLoading=null;render();return}render();jobTimer=setTimeout(()=>pollJob(id,revision),450)}catch(e){if(revision!==state.backtestRevision)return;state.busy=false;state.defaultLoading=null;toast(e.message);render()}}
async function saveVariant(form,item){const {raw,params}=paramsFromForm(form,item);const saved=await api('/api/strategy-variants',{id:raw.variantId||undefined,strategyId:item.id,name:raw.name,description:raw.description,code:raw.code,params});state.variants=await api('/api/strategy-variants');state.variant=saved;state.paramEditing=true;toast(`已保存配置 v${saved.version}；重新回测后更新结果`);render()}
async function savePlan(){if(state.result?.status!=='ok'||state.paramEditing||state.busy)return;const item=findStrategy(state.selected),r=state.result,target=r.fundCode||'固定行业基金池';state.planToSave={strategyId:item.id,code:r.fundCode,fundPool:r.fundPool,amount:r.parameters?.amount??r.parameters?.initial_capital,params:{...r.parameters},name:`${item.name} · ${target}`,runId:r.runId,dataAsOf:r.dataAsOf};$('#panda-dialog-content').innerHTML=`<div class="panda-dialog-head"><div><h2>保存为个人计划</h2><p>${esc(item.name)} · ${esc(target)}</p></div><button data-action="close-dialog">×</button></div><div class="panda-plan-confirm"><p>请核对标的与资金安排。保存后为草稿，需要你另行开启跟踪。</p><dl>${(item.params||[]).map(x=>`<dt>${esc(x.label)}</dt><dd>${esc(r.parameters?.[x.key]??'—')} ${esc(x.unit||'')}</dd>`).join('')}</dl>${r.fundPool?`<p>基金池：${esc(JSON.stringify(r.fundPool))}</p>`:''}<p class="panda-essential-note">使用本次回测配置，不会提交真实交易。</p>${button('确认保存','confirm-save-plan','','primary')}</div>`;$('#panda-dialog').showModal()}
async function confirmSavePlan(){if(!state.planToSave||state.planSaving)return;state.planSaving=true;try{await api('/api/strategy-plans',state.planToSave);state.planToSave=null;$('#panda-dialog').close();state.plans=await api('/api/strategy-plans');toast('已保存为计划草稿，可在“我的计划”开启跟踪');render()}finally{state.planSaving=false}}
async function planAction(id,action){await api('/api/strategy-plans/action',{id,action});state.plans=await api('/api/strategy-plans');render()}
async function refreshPlanPerformance(){if(state.planPerformanceLoading||!state.plans.some(plan=>n(plan.performance?.excessReturnPct)===null||n(plan.performance?.benchmarkReturnPct)===null))return;state.planPerformanceLoading=true;render();try{state.plans=await api('/api/strategy-plans/refresh-performance',{});state.runs=await api('/api/strategy-runs')}catch(e){toast(e.message)}finally{state.planPerformanceLoading=false;render()}}
async function checkPlans(){if(!state.plans.some(x=>x.status==='active'))return;try{await api('/api/strategy-plans/check-all',{});state.plans=await api('/api/strategy-plans');if(state.nav==='plans')render()}catch{}}
function startMonitor(){clearInterval(planMonitorTimer);checkPlans();planMonitorTimer=setInterval(checkPlans,30*60*1000)}
async function openRun(id){const run=state.runs.find(x=>x.id===id);if(!run)return;state.drill=null;state.agentPageFocus=null;state.runFocus=id;const result=run.result||{status:run.status,strategyId:run.strategyId,strategyVersion:run.strategyVersion,fundCode:run.fundCode,dataAsOf:run.dataAsOf,period:run.period,parameters:run.parameters,metrics:run.metrics,cashFlow:run.cashFlow,benchmarkName:run.benchmarkName,source:run.source,missingData:run.missingData,trades:null},dialog=$('#panda-dialog'),host=$('#panda-dialog-content'),params=Object.entries(result.parameters||{}).map(([key,value])=>`<span><b>${esc(findStrategy(run.strategyId)?.params?.find(x=>x.key===key)?.label||key)}</b>${esc(value)}</span>`).join('');host.innerHTML=`<div class="panda-dialog-head"><div><small>回测记录</small><h2>${esc(findStrategy(run.strategyId)?.name||run.strategyId)}</h2><p>${esc(run.fundCode||'行业基金池')} · Skill v${esc(run.strategyVersion)} · ${esc(dt(run.createdAt))}</p></div>${button('问 Agent','ask-agent-about-page','','quiet')}<button data-action="close-dialog">×</button></div>${disclosure('回测配置 · 策略 v'+esc(run.strategyVersion),`<div class="panda-run-params">${params||'<span>旧记录未保存参数</span>'}</div>`)}<div class="panda-dialog-result">${resultView(result,false)}</div>`;dialog.showModal()}
async function drillFund(code){state.runFocus=null;state.agentPageFocus=null;state.drill=null;const dialog=$('#panda-dialog'),host=$('#panda-dialog-content');host.innerHTML='<div class="panda-loading"><i></i>正在读取真实复权净值…</div>';dialog.showModal();try{const d=await api('/api/fund/nav?code='+encodeURIComponent(code));state.drill=d;host.innerHTML=`<div class="panda-dialog-head"><div><small>基金详情</small><h2>${esc(d.name)}</h2><p>${esc(d.code)} · 数据截至 ${esc(d.dataAsOf)} · ${esc(d.source)}</p></div>${button('问 Agent','ask-agent-about-page','','quiet')}<button data-action="close-dialog">×</button></div><div class="panda-chart-wrap">${lineChart(d.points)}</div><div class="panda-result-note">基金经理：${esc(d.manager||'接口未提供')}。曲线展示复权净值累计变化，不代表个人账户收益。</div><div class="panda-detail-actions">${button('带入策略回测','pick-for-strategy',`data-code="${esc(code)}"`,'primary')}</div>`}catch(e){host.innerHTML=`<div class="panda-result-blocked"><b>!</b><div><strong>下钻失败</strong><p>${esc(e.message)}</p></div></div>`}}
function accountLoginMarkup(force,confirm=false){const title=force?'切换同花顺账户':'连接同花顺账户',desc=force?'扫码成功后，本机当前授权会替换为新账户。策略、回测和本地计划不会被删除。':'使用同花顺 App 扫描官方授权页二维码，并在手机上确认授权。';return `<div class="panda-dialog-head"><div><h2>${title}</h2><p>${desc}</p></div><button data-action="close-dialog">×</button></div><div class="panda-login-body"><div class="panda-login-visual"><div class="panda-phone-mark"><i></i><b>⌁</b></div><span>${confirm?'准备重新授权':'二维码显示在已打开的官方授权页'}</span></div><div class="panda-login-copy"><ol><li>打开手机同花顺 App</li><li>扫描浏览器官方授权页中的二维码</li><li>在手机上确认后等待本页自动更新</li></ol><div id="panda-login-status" class="panda-login-status ${confirm?'warning':'running'}"><i></i><span>${confirm?'确认后将强制发起新账号扫码授权。':esc(state.accountLoginMessage||'正在打开官方授权页…')}</span></div><p>工作台不会读取二维码内容、登录凭据、完整账户号或银行卡号。</p></div></div><div class="panda-login-footer">${confirm?`${button('取消','close-dialog','','quiet')}${button('开始扫码切换','confirm-switch-account','','primary')}`:button('关闭窗口','close-dialog','','quiet')}</div>`}
function showAccountLoginDialog(force,confirm=false){const dialog=$('#panda-dialog'),host=$('#panda-dialog-content');host.innerHTML=accountLoginMarkup(force,confirm);if(!dialog.open)dialog.showModal()}
function updateAccountLoginDialog(message,status='running'){const node=$('#panda-login-status');if(!node)return;node.className=`panda-login-status ${status}`;node.innerHTML=`<i></i><span>${esc(message)}</span>`}
async function loginFund(force=false){state.accountBusy=true;state.accountLoginMode=force?'switch':'login';state.accountLoginMessage='正在打开官方授权页…';state.accountLoginOpenedUrl='';render();showAccountLoginDialog(force);try{const started=await api('/api/fund/login',{force});state.accountLoginMessage=started.message;updateAccountLoginDialog(started.message);pollLogin()}catch(e){state.accountBusy=false;state.accountLoginMessage=e.message;updateAccountLoginDialog(e.message,'failed');toast(e.message);render()}}
async function pollLogin(){try{const r=await api('/api/fund/login-status');state.accountLoginMessage=r.message;if(r.authUrl&&r.authUrl!==state.accountLoginOpenedUrl){state.accountLoginOpenedUrl=r.authUrl;try{if(D.enabled)await desktopCall(window.fundDesktop.openFundLoginUrl(r.authUrl));else window.open(r.authUrl,'_blank','noopener');state.accountLoginMessage='官方扫码授权页已在系统浏览器打开，请使用同花顺 App 扫码并确认。'}catch(e){state.accountLoginMessage=`扫码页自动打开失败：${e.message}`}}if(r.running){updateAccountLoginDialog(state.accountLoginMessage);setTimeout(pollLogin,2200);return}state.accountBusy=false;updateAccountLoginDialog(state.accountLoginMessage||r.message,r.success?'success':'failed');toast(state.accountLoginMessage||r.message);if(r.success){state.holdings=null;state.holdingsError='';state.analysis=null;render();loadHoldings()}else render()}catch(e){state.accountBusy=false;state.accountLoginMessage=e.message;updateAccountLoginDialog(e.message,'failed');toast(e.message);render()}}

function shareResultForPlan(plan){const run=state.runs.find(x=>x.id===plan.backtestRunId);return run?.result||null}
function shareParamsPayload(result,item){const params={};for(const spec of item.params||[]){const value=result.parameters?.[spec.key]??item.defaultParams?.[spec.key]??spec.default;if(value!==undefined)params[spec.key]=value}return params}
function strategyShareCaption(channel,card){const where={wechat:'微信聊天',moments:'朋友圈',xiaohongshu:'小红书',tonghuashun:'同花顺'}[channel]||'策略分享';const result=card.result,m=result.metrics||{};return `${where}｜${card.strategyName}\n${card.fundName}${card.result.fundCode?`（${card.result.fundCode}）`:''}\n超额收益 ${pct(m.excessReturnPct)} · 绝对收益 ${pct(m.absoluteReturnPct??m.returnPct)} · 年化波动 ${n(m.volatilityPct)===null?'—':num(m.volatilityPct)+'%'}\n回测区间 ${result.period?.start||'—'} 至 ${result.period?.end||result.dataAsOf||'—'}\n历史回测不代表未来收益。`}
function roundedRect(ctx,x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function fitText(ctx,text,maxWidth,size,family='sans-serif',weight=600){let px=size;ctx.font=`${weight} ${px}px ${family}`;while(ctx.measureText(text).width>maxWidth&&px>24){px-=2;ctx.font=`${weight} ${px}px ${family}`}return px}
